"""Export only registered result counts into the thesis; do not rerun the test."""
import json
from pathlib import Path

HERE = Path(__file__).resolve().parent
r = json.loads((HERE/'R_multiasset.json').read_text())
assert r['passed'] == sum(c['pass'] for c in r['cases'])
assert r['total'] == len(r['cases'])
(HERE/'multiasset_numbers.tex').write_text(
    '% Generated by checks/export_multiasset_numbers.py from R_multiasset.json\n'
    f'\\newcommand{{\\MultiassetCases}}{{{r["total"]}}}\n'
    f'\\newcommand{{\\MultiassetPassed}}{{{r["passed"]}}}\n')
